import { Observable } from "@babylonjs/core";
import type { FreezeReport, GraphSnapshot } from "@graphty/graph-format";

import type { EdgeId, NodeId } from "../catalog/types";
import type { ImportReport } from "../data/report";
import type {
    DataLoadingCompleteEvent,
    DataLoadingErrorEvent,
    DataLoadingErrorSummaryEvent,
    DataLoadingProgressEvent,
    EdgeEvent,
    ElementsRemovedEvent,
    EmittableEventType,
    EventCallbackType,
    EventType,
    GraphDataAddedEvent,
    GraphDataClearedEvent,
    GraphDataLoadedEvent,
    GraphErrorEvent,
    GraphEvent,
    GraphGenericEvent,
    GraphLayoutInitializedEvent,
    GraphSettledEvent,
    GraphSnapshotDroppedEvent,
    GraphSnapshotReplacedEvent,
    NodeEvent,
    SelectionChangedEvent,
} from "../events";
import type { Graph } from "../Graph";
import type { HistoryCause } from "../session/types";
import type { GraphContext } from "./GraphContext";
import type { Manager } from "./interfaces";

/**
 * Centralized event management for the Graph system
 * Handles all graph, node, and edge events with type safety
 */
export class EventManager implements Manager {
    // Observables for different event types
    private readonly graphObservable = new Observable<GraphEvent>();
    private readonly nodeObservable = new Observable<NodeEvent>();
    private readonly edgeObservable = new Observable<EdgeEvent>();

    // Expose for testing and advanced usage
    /**
     * Gets the graph event observable for direct subscription
     * @returns Observable for graph events
     */
    get onGraphEvent(): Observable<GraphEvent> {
        return this.graphObservable;
    }

    /**
     * Gets the node event observable for direct subscription.
     *
     * The element forwards it to the DOM the way it forwards {@link EventManager.onGraphEvent},
     * which is what makes a click, a hover and a drag reachable by a consumer holding only the
     * tag. Before that forwarder existed, every node event was emitted onto a private observable
     * and landed nowhere.
     * @returns Observable for node events
     */
    get onNodeEvent(): Observable<NodeEvent> {
        return this.nodeObservable;
    }

    /**
     * Gets the graph error observable for direct subscription
     * @returns Observable for graph error events
     */
    get onGraphError(): Observable<GraphErrorEvent> {
        return this.graphObservable as Observable<GraphErrorEvent>;
    }

    // Track observers for cleanup
    // Using any here is required due to BabylonJS Observable/Observer type limitations
    private readonly observers = new Map<
        symbol,
        {
            type: "graph" | "node" | "edge";
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            observable: any;
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            observer: any;
        }
    >();

    // Error handling configuration
    private readonly errorRetryCount = 3;
    private readonly errorRetryDelay = 1000; // ms

    /**
     * Initializes the event manager
     * @returns Promise that resolves when initialization is complete
     */
    async init(): Promise<void> {
        // EventManager doesn't need async initialization
        return Promise.resolve();
    }

    /**
     * Disposes of the event manager and cleans up all resources
     */
    dispose(): void {
        // Clear all observers
        for (const { observable, observer } of this.observers.values()) {
            observable.remove(observer);
        }
        this.observers.clear();

        // Clear observables
        this.graphObservable.clear();
        this.nodeObservable.clear();
        this.edgeObservable.clear();
    }

    // Graph Events

    /**
     * Emits a graph settled event when the graph layout has stabilized
     * @param graph - Graph instance that has settled
     */
    emitGraphSettled(graph: Graph): void {
        const event: GraphSettledEvent = {
            type: "graph-settled",
            graph,
        };
        this.graphObservable.notifyObservers(event);
    }

    /**
     * Emits a graph error event
     * @param graph - Graph or GraphContext instance where the error occurred
     * @param error - Error object
     * @param context - Error context category
     * @param details - Additional error details
     */
    emitGraphError(
        graph: Graph | GraphContext | null,
        error: Error,
        context: GraphErrorEvent["context"],
        details?: Record<string, unknown>,
    ): void {
        const event: GraphErrorEvent = {
            type: "error",
            graph: graph as Graph | null,
            error,
            context,
            details,
        };
        this.graphObservable.notifyObservers(event);
    }

    /**
     * Emits a data loaded event when data has been loaded from a source
     * @param graph - Graph or GraphContext instance
     * @param chunksLoaded - Number of data chunks loaded
     * @param dataSourceType - Type of data source used
     * @param report - What the load did, including which endpoint spelling resolved
     * @param loadId - Which load this is, when it is one
     */
    emitGraphDataLoaded(
        graph: Graph | GraphContext,
        chunksLoaded: number,
        dataSourceType: string,
        report: ImportReport,
        loadId?: number,
    ): void {
        const event: GraphDataLoadedEvent = {
            type: "data-loaded",
            graph: graph as Graph,
            details: {
                chunksLoaded,
                dataSourceType,
                report,
                ...(loadId === undefined ? {} : { loadId }),
            },
        };
        this.graphObservable.notifyObservers(event);
    }

    /**
     * Emits the removal event naming every node and edge one removal call took away.
     * @param nodes - the nodes that were removed
     * @param edges - every edge that was attached to one of them
     * @param cause - what removed them, when it came through the history
     */
    emitElementsRemoved(nodes: NodeId[], edges: EdgeId[], cause?: HistoryCause): void {
        const event: ElementsRemovedEvent = {
            type: "elements-removed",
            nodes,
            edges,
            ...(cause === undefined ? {} : { cause }),
        };
        this.graphObservable.notifyObservers(event);
    }

    /**
     * Emits a data added event when nodes or edges are added
     * @param dataType - Type of data added (nodes or edges)
     * @param count - Number of items added
     * @param shouldStartLayout - Whether layout should be started
     * @param shouldZoomToFit - Whether to zoom to fit the data
     * @param cause - what added them, when it came through the history
     */
    emitDataAdded(
        dataType: "nodes" | "edges",
        count: number,
        shouldStartLayout: boolean,
        shouldZoomToFit: boolean,
        cause?: HistoryCause,
    ): void {
        const event: GraphDataAddedEvent = {
            type: "data-added",
            dataType,
            count,
            shouldStartLayout,
            shouldZoomToFit,
            ...(cause === undefined ? {} : { cause }),
        };
        this.graphObservable.notifyObservers(event);
    }

    /**
     * Emit `snapshot-replaced` (graph-format design 14.4 rule 11).
     *
     * ELEMENT-INTERNAL. This event is listed in `INTERNAL_EVENT_TYPES` (events.ts) and therefore
     * never reaches the DOM: its payload is a `Graph` plus two typed-array-backed snapshots, which
     * a `CustomEvent` detail cannot carry across a structured clone. Internal listeners still get
     * it through `onGraphEvent` and `addListener` as usual.
     * @param graph - the graph whose data changed; DataManager holds a GraphContext, so this takes
     *     the same union emitGraphError takes and casts once, here
     * @param previous - the superseded snapshot, or null on the first freeze
     * @param next - the new snapshot, with the element position column already attached
     * @param report - freezeWithReport's report
     */
    emitSnapshotReplaced(
        graph: Graph | GraphContext,
        previous: GraphSnapshot | null,
        next: GraphSnapshot,
        report: FreezeReport,
    ): void {
        const event: GraphSnapshotReplacedEvent = {
            type: "snapshot-replaced",
            graph: graph as Graph,
            previous,
            next,
            report,
        };
        this.graphObservable.notifyObservers(event);
    }

    /**
     * Emit `snapshot-dropped`: the store was discarded and every snapshot it froze is gone.
     *
     * ELEMENT-INTERNAL, for the same reason `snapshot-replaced` is. Emitted while the outgoing
     * store is still alive, so a listener releasing a snapshot can still derive from it.
     */
    emitSnapshotDropped(): void {
        const event: GraphSnapshotDroppedEvent = { type: "snapshot-dropped" };
        this.graphObservable.notifyObservers(event);
    }

    /**
     * Emits the public announcement that the graph's data was cleared.
     */
    emitDataCleared(): void {
        const event: GraphDataClearedEvent = { type: "data-cleared" };
        this.graphObservable.notifyObservers(event);
    }

    /**
     * Emits a layout initialized event when a layout is ready
     * @param layoutType - Type of layout that was initialized
     * @param shouldZoomToFit - Whether to zoom to fit after initialization
     */
    emitLayoutInitialized(layoutType: string, shouldZoomToFit: boolean): void {
        const event: GraphLayoutInitializedEvent = {
            type: "layout-initialized",
            layoutType,
            shouldZoomToFit,
        };
        this.graphObservable.notifyObservers(event);
    }

    /**
     * Emits a graph or AI event on the graph channel, which `addListener` and the element's DOM
     * forwarder both deliver. The name must be one the `GraphEvent` or `AiEvent` union declares
     * (or one of the few legacy names in `UndeclaredEventType`), so a new undeclared name fails to
     * compile here rather than reaching listeners untyped.
     * @param type - A declared graph or AI event type
     * @param data - The event's fields besides `type`
     */
    emit(type: EmittableEventType, data: Record<string, unknown>): void {
        const event = { type, ...data } as GraphGenericEvent;
        this.graphObservable.notifyObservers(event);
    }

    /**
     * Emits a graph event under any name.
     * @param type - Event type identifier
     * @param data - Event data payload
     * @deprecated Use {@link EventManager.emit}, which accepts only declared event names. This
     * method will accept only those names in the next major release.
     */
    emitGraphEvent(type: string, data: Record<string, unknown>): void {
        this.emit(type as EmittableEventType, data);
    }

    // Data Loading Events

    /**
     * Emits a data loading progress event during data import
     * @param format - Data format being loaded
     * @param bytesProcessed - Number of bytes processed so far
     * @param totalBytes - Total bytes to process (if known)
     * @param nodeRecordsLoaded - How many node RECORDS the source has handed over so far
     * @param edgeRecordsLoaded - How many edge RECORDS the source has handed over so far
     * @param chunksProcessed - Number of data chunks processed
     * @param loadId - Which load this is, when it is one
     */
    emitDataLoadingProgress(
        format: string,
        bytesProcessed: number,
        totalBytes: number | undefined,
        nodeRecordsLoaded: number,
        edgeRecordsLoaded: number,
        chunksProcessed: number,
        loadId?: number,
    ): void {
        const event: DataLoadingProgressEvent = {
            type: "data-loading-progress",
            format,
            bytesProcessed,
            totalBytes,
            percentage: totalBytes ? (bytesProcessed / totalBytes) * 100 : undefined,
            nodeRecordsLoaded,
            edgeRecordsLoaded,
            chunksProcessed,
            ...(loadId === undefined ? {} : { loadId }),
        };
        this.graphObservable.notifyObservers(event);
    }

    /**
     * Emits a data loading error event when an error occurs during import
     * @param error - Error object
     * @param context - Error context category
     * @param format - Data format being loaded
     * @param details - Error details
     * @param details.line - Line number where error occurred
     * @param details.nodeId - Node ID related to error
     * @param details.edgeId - Edge ID related to error
     * @param details.canContinue - Whether loading can continue after this error
     * @param details.loadId - Which load this is, when it is one
     */
    emitDataLoadingError(
        error: Error,
        context: DataLoadingErrorEvent["context"],
        format: string | undefined,
        details: {
            line?: number;
            nodeId?: unknown;
            edgeId?: string;
            canContinue: boolean;
            loadId?: number;
        },
    ): void {
        const event: DataLoadingErrorEvent = {
            type: "data-loading-error",
            error,
            context,
            format,
            ...details,
        };
        this.graphObservable.notifyObservers(event);
    }

    /**
     * Emits a summary of all data loading errors after import completes
     * @param format - Data format that was loaded
     * @param totalErrors - Total number of errors encountered
     * @param message - Summary message describing errors
     * @param detailedReport - Detailed error report
     * @param primaryCategory - Primary error category
     * @param suggestion - Suggested fix for the errors
     * @param loadId - Which load this is, when it is one
     */
    emitDataLoadingErrorSummary(
        format: string,
        totalErrors: number,
        message: string,
        detailedReport: string,
        primaryCategory?: string,
        suggestion?: string,
        loadId?: number,
    ): void {
        const event: DataLoadingErrorSummaryEvent = {
            type: "data-loading-error-summary",
            format,
            totalErrors,
            primaryCategory,
            message,
            suggestion,
            detailedReport,
            ...(loadId === undefined ? {} : { loadId }),
        };
        this.graphObservable.notifyObservers(event);
    }

    /**
     * Emits a data loading complete event when import finishes
     * @param format - Data format that was loaded
     * @param nodesLoaded - How many nodes the graph HOLDS, not how many records arrived
     * @param edgesLoaded - How many edges the graph HOLDS, not how many records arrived
     * @param duration - Time taken to load in milliseconds
     * @param errors - Number of errors encountered
     * @param warnings - Number of warnings encountered
     * @param success - Whether loading was successful
     * @param report - What the load did, including which endpoint spelling resolved
     * @param loadId - Which load this is, when it is one
     */
    emitDataLoadingComplete(
        format: string,
        nodesLoaded: number,
        edgesLoaded: number,
        duration: number,
        errors: number,
        warnings: number,
        success: boolean,
        report: ImportReport,
        loadId?: number,
    ): void {
        const event: DataLoadingCompleteEvent = {
            type: "data-loading-complete",
            format,
            nodesLoaded,
            edgesLoaded,
            duration,
            errors,
            warnings,
            success,
            report,
            ...(loadId === undefined ? {} : { loadId }),
        };
        this.graphObservable.notifyObservers(event);
    }

    // Selection Events

    /**
     * Emits a selection changed event when node selection changes
     * @param previousNode - Previously selected node (or null)
     * @param currentNode - Currently selected node (or null)
     */
    emitSelectionChanged(
        previousNode: SelectionChangedEvent["previousNode"],
        currentNode: SelectionChangedEvent["currentNode"],
    ): void {
        const event: SelectionChangedEvent = {
            type: "selection-changed",
            previousNode,
            currentNode,
            previousNodeId: previousNode?.id ?? null,
            currentNodeId: currentNode?.id ?? null,
        };
        this.graphObservable.notifyObservers(event);
    }

    // Node Events

    /**
     * Emits a node event
     * @param type - Node event type
     * @param eventData - Event data (excluding type field)
     */
    emitNodeEvent(type: NodeEvent["type"], eventData: object): void {
        const event = { type, ...eventData } as NodeEvent;
        this.nodeObservable.notifyObservers(event);
    }

    // Edge Events

    /**
     * Emits an edge event
     * @param type - Edge event type
     * @param eventData - Event data (excluding type field)
     */
    emitEdgeEvent(type: EdgeEvent["type"], eventData: object): void {
        const event = { type, ...eventData } as EdgeEvent;
        this.edgeObservable.notifyObservers(event);
    }

    // Event Listeners

    /**
     * Add a listener for a specific event type
     * Returns a symbol that can be used to remove the listener
     * @param type - Event type to listen for
     * @param callback - Callback function to invoke when event occurs
     * @returns Symbol ID that can be used to remove the listener
     */
    addListener(type: EventType, callback: EventCallbackType): symbol {
        const id = Symbol("event-listener");

        switch (type) {
            case "graph-settled":
            case "error":
            case "data-loaded":
            case "data-added":
            case "data-cleared":
            case "snapshot-replaced":
            case "snapshot-dropped":
            case "layout-initialized":
            case "render-initialized":
            case "manager-initialized":
            case "lifecycle-initialized":
            case "lifecycle-disposed":
            case "skybox-loaded":
            case "operation-queue-active":
            case "operation-queue-idle":
            case "operation-batch-complete":
            case "operation-start":
            case "operation-complete":
            case "operation-progress":
            case "layout-progress":
            case "operation-obsoleted":
            case "animation-progress":
            case "animation-cancelled":
            case "screenshot-enhancing":
            case "screenshot-ready":
            case "style-changed":
            case "camera-state-changed":
            case "data-loading-progress":
            case "data-loading-error":
            case "data-loading-error-summary":
            case "data-loading-complete":
            case "zoom-to-fit-complete":
            case "graph-frame-stable":
            case "elements-removed":
            case "selection-changed":
            case "graph-started":
            case "layout-changed":
            case "layout-warning":
            case "operation-cancelled":
            case "stats-update":
            case "input-enabled-changed":
            case "xr-session-started":
            case "xr-session-ended":
            case "input:pointer-down":
            case "input:pointer-move":
            case "input:pointer-up":
            case "input:wheel":
            case "input:touch-start":
            case "input:touch-move":
            case "input:touch-end":
            case "input:key-down":
            case "input:key-up":
            case "input:undo":
            case "input:redo":
            case "input:select-all":
            case "ai-status-change":
            case "ai-command-start":
            case "ai-command-complete":
            case "ai-command-error":
            case "ai-command-cancelled":
            case "ai-stream-chunk":
            case "ai-stream-tool-call":
            case "ai-stream-tool-result":
            case "ai-voice-start":
            case "ai-voice-transcript":
            case "ai-voice-end": {
                // The ai-* events travel on the graph observable too (see AiManager), so the
                // element's DOM forwarder delivers them as well.
                const observer = this.graphObservable.add((event) => {
                    if (event.type === type) {
                        callback(event);
                    }
                });
                this.observers.set(id, {
                    type: "graph",
                    observable: this.graphObservable,
                    observer,
                });
                break;
            }

            case "node-update-after":
            case "node-update-before":
            case "node-add-before":
            case "node-click":
            case "node-hover":
            case "node-drag-start":
            case "node-drag-end": {
                const observer = this.nodeObservable.add((event) => {
                    if (event.type === type) {
                        callback(event);
                    }
                });
                this.observers.set(id, {
                    type: "node",
                    observable: this.nodeObservable,
                    observer,
                });
                break;
            }

            case "edge-update-after":
            case "edge-update-before":
            case "edge-add-before": {
                const observer = this.edgeObservable.add((event) => {
                    if (event.type === type) {
                        callback(event);
                    }
                });
                this.observers.set(id, {
                    type: "edge",
                    observable: this.edgeObservable,
                    observer,
                });
                break;
            }

            default: {
                // A declared event with no case above fails to compile here.
                const unhandled: never = type;
                throw new TypeError(`Unknown event type: ${String(unhandled)}`);
            }
        }

        return id;
    }

    /**
     * Remove a listener by its ID
     * @param id - Symbol ID returned from addListener
     * @returns True if listener was removed, false if not found
     */
    removeListener(id: symbol): boolean {
        const entry = this.observers.get(id);
        if (!entry) {
            return false;
        }

        entry.observable.remove(entry.observer);
        this.observers.delete(id);
        return true;
    }

    /**
     * Get the total number of registered listeners
     * @returns Number of active listeners
     */
    listenerCount(): number {
        return this.observers.size;
    }

    /**
     * Add a one-time listener that automatically removes itself after firing
     * @param type - Event type to listen for
     * @param callback - Callback function to invoke when event occurs
     * @returns Symbol ID that can be used to remove the listener
     */
    once(type: EventType, callback: EventCallbackType): symbol {
        const id = this.addListener(type, (event) => {
            callback(event);
            this.removeListener(id);
        });
        return id;
    }

    /**
     * Wait for a specific event to occur
     * Returns a promise that resolves with the event
     * @param type - Event type to wait for
     * @param timeout - Optional timeout in milliseconds
     * @returns Promise that resolves with the event or rejects on timeout
     */
    waitFor(
        type: EventType,
        timeout?: number,
    ): Promise<GraphEvent | NodeEvent | EdgeEvent | import("../events").AiEvent> {
        return new Promise((resolve, reject) => {
            const timeoutId = timeout
                ? setTimeout(() => {
                      this.removeListener(listenerId);
                      reject(new Error(`Timeout waiting for event: ${type}`));
                  }, timeout)
                : undefined;

            const listenerId = this.once(type, (event) => {
                if (timeoutId) {
                    clearTimeout(timeoutId);
                }

                resolve(event);
            });
        });
    }

    // Error Handling with Retry

    /**
     * Execute an async operation with automatic retry on failure
     * Emits error events for each failure
     * @param operation - Async operation to execute
     * @param context - Error context category
     * @param graph - Graph or GraphContext instance
     * @param details - Additional error details
     * @returns Promise that resolves with operation result or rejects after all retries fail
     */
    async withRetry<T>(
        operation: () => Promise<T>,
        context: GraphErrorEvent["context"],
        graph: Graph | GraphContext | null,
        details?: Record<string, unknown>,
    ): Promise<T> {
        let lastError: Error | undefined;

        for (let attempt = 0; attempt < this.errorRetryCount; attempt++) {
            try {
                return await operation();
            } catch (error) {
                lastError = error instanceof Error ? error : new Error(String(error));

                // Emit error event for this attempt
                this.emitGraphError(graph, lastError, context, {
                    ...details,
                    attempt: attempt + 1,
                    maxAttempts: this.errorRetryCount,
                });

                // Don't delay after the last attempt
                if (attempt < this.errorRetryCount - 1) {
                    // Exponential backoff
                    const delay = this.errorRetryDelay * Math.pow(2, attempt);
                    await new Promise((resolve) => setTimeout(resolve, delay));
                }
            }
        }

        // All attempts failed
        throw lastError ?? new Error("Operation failed with no recorded error");
    }
}
