import type { Vector2 } from "@babylonjs/core/Maths/math.vector";
import { Observable } from "@babylonjs/core/Misc/observable";

import type { GraphEventType, InputEnabledChangedEvent } from "../events";
import { BabylonInputSystem } from "../input/babylon-input-system";
import { MockDeviceInputSystem } from "../input/mock-device-input-system";
import type { KeyboardInfo, MouseButton, PointerInfo, TouchPoint, WheelInfo } from "../input/types";
import { downloadBlob } from "../utils/download";
import type { Manager, ManagerContext } from "./interfaces";

/**
 * Recorded input event structure
 */
export interface RecordedInputEvent {
    timestamp: number;
    type: string;
    data: Record<string, unknown>;
}

/**
 * Configuration options for InputManager
 */
export interface InputManagerConfig {
    /**
     * Whether to use mock input system for testing
     */
    useMockInput?: boolean;

    /**
     * Whether touch input is enabled
     */
    touchEnabled?: boolean;

    /**
     * Whether keyboard input is enabled
     */
    keyboardEnabled?: boolean;

    /**
     * Whether pointer lock is enabled for FPS-style controls
     */
    pointerLockEnabled?: boolean;

    /**
     * Input recording/playback for automation
     */
    recordInput?: boolean;
    playbackFile?: string;

    /**
     * Whether Mod+Z undoes and Shift+Mod+Z or Mod+Y redoes, through {@link InputManagerConfig.history}.
     * On by default. A handled key has its default prevented, so a host binding the same keys
     * skips events with `defaultPrevented` set.
     */
    historyKeys?: boolean;

    /** What the history keys call: the graph's session. */
    history?: { undo(): unknown; redo(): unknown };
}

/**
 * Manages all user input for the graph
 * Provides a unified interface for mouse, keyboard, and touch input
 */
export class InputManager implements Manager {
    // Observable events. They outlive the input system behind them, which playback swaps for a
    // mock one, so a subscriber (and the `input:*` bridge) keeps hearing input (issue #3002).
    public readonly onPointerMove = new Observable<PointerInfo>();
    public readonly onPointerDown = new Observable<PointerInfo>();
    public readonly onPointerUp = new Observable<PointerInfo>();
    public readonly onWheel = new Observable<WheelInfo>();
    public readonly onTouchStart = new Observable<TouchPoint[]>();
    public readonly onTouchMove = new Observable<TouchPoint[]>();
    public readonly onTouchEnd = new Observable<number[]>();
    public readonly onKeyDown = new Observable<KeyboardInfo>();
    public readonly onKeyUp = new Observable<KeyboardInfo>();

    private inputSystem: BabylonInputSystem | MockDeviceInputSystem;
    private enabled = true;
    private recordedEvents: RecordedInputEvent[] = [];
    private playbackIndex = 0;
    private playbackStartTime = 0;

    /**
     * Creates an instance of InputManager
     * @param context - Manager context providing access to scene, canvas, and event manager
     * @param config - Input manager configuration options
     */
    constructor(
        private readonly context: ManagerContext,
        private readonly config: InputManagerConfig = {},
    ) {
        // Create appropriate input system based on config
        this.inputSystem = this.config.useMockInput
            ? new MockDeviceInputSystem()
            : new BabylonInputSystem(this.context.scene);

        this.forwardInput(this.inputSystem);
    }

    /**
     * Pass everything an input system observes on to this manager's observables.
     * @param system - The input system now in use
     */
    private forwardInput(system: BabylonInputSystem | MockDeviceInputSystem): void {
        const forward = <T>(from: Observable<T>, to: Observable<T>): void => {
            from.add((info) => {
                to.notifyObservers(info);
            });
        };
        forward(system.onPointerMove, this.onPointerMove);
        forward(system.onPointerDown, this.onPointerDown);
        forward(system.onPointerUp, this.onPointerUp);
        forward(system.onWheel, this.onWheel);
        forward(system.onTouchStart, this.onTouchStart);
        forward(system.onTouchMove, this.onTouchMove);
        forward(system.onTouchEnd, this.onTouchEnd);
        forward(system.onKeyDown, this.onKeyDown);
        forward(system.onKeyUp, this.onKeyUp);
    }

    /**
     * Initializes the input manager and sets up event bridges
     */
    async init(): Promise<void> {
        try {
            // Attach input system to canvas
            this.inputSystem.attach(this.context.canvas);

            // Set up event bridges to EventManager
            this.setupEventBridges();

            // Load playback file if specified
            if (this.config.playbackFile) {
                await this.loadPlaybackFile(this.config.playbackFile);
            }

            // Emit initialization event
            this.context.eventManager.emit("input-initialized", {
                inputManager: this,
                config: this.config,
            });
        } catch (error) {
            const err = error instanceof Error ? error : new Error(String(error));
            this.context.eventManager.emitGraphError(null, err, "init", { component: "InputManager" });
            throw new Error(`Failed to initialize InputManager: ${err.message}`);
        }
    }

    /**
     * Disposes of the input manager and cleans up resources
     */
    dispose(): void {
        // Save recorded events if recording
        if (this.config.recordInput && this.recordedEvents.length > 0) {
            this.saveRecordedEvents();
        }

        // Dispose input system
        this.inputSystem.dispose();
        for (const observable of [
            this.onPointerMove,
            this.onPointerDown,
            this.onPointerUp,
            this.onWheel,
            this.onTouchStart,
            this.onTouchMove,
            this.onTouchEnd,
            this.onKeyDown,
            this.onKeyUp,
        ]) {
            observable.clear();
        }

        // Clear references
        this.recordedEvents = [];
    }

    /**
     * Enable or disable all input
     * @param enabled - Whether input should be enabled
     */
    setEnabled(enabled: boolean): void {
        this.enabled = enabled;

        if (!enabled && this.inputSystem instanceof BabylonInputSystem) {
            // Clear any active states when disabling
            this.inputSystem.detach();
        } else if (enabled && this.inputSystem instanceof BabylonInputSystem) {
            this.inputSystem.attach(this.context.canvas);
        }

        this.context.eventManager.emit("input-enabled-changed", { enabled } satisfies Omit<
            InputEnabledChangedEvent,
            "type"
        >);
    }

    /**
     * Get the current pointer position
     * @returns Current pointer position as Vector2
     */
    getPointerPosition(): Vector2 {
        return this.inputSystem.getPointerPosition();
    }

    /**
     * Check if a pointer button is currently down
     * @param button - Mouse button to check (left, middle, right)
     * @returns True if the button is pressed, false otherwise
     */
    isPointerDown(button?: MouseButton): boolean {
        return this.inputSystem.isPointerDown(button);
    }

    /**
     * Get all active touch points
     * @returns Array of active touch points
     */
    getActiveTouches(): TouchPoint[] {
        return this.inputSystem.getActiveTouches();
    }

    /**
     * Get the mock input system for testing
     * @returns MockDeviceInputSystem instance
     * @throws Error if not using mock input
     */
    getMockInputSystem(): MockDeviceInputSystem {
        if (!(this.inputSystem instanceof MockDeviceInputSystem)) {
            throw new Error("Not using mock input system");
        }

        return this.inputSystem;
    }

    /**
     * Start recording input events
     */
    startRecording(): void {
        this.config.recordInput = true;
        this.recordedEvents = [];
        this.context.eventManager.emit("input-recording-started", {});
    }

    /**
     * Stop recording input events
     * @returns Array of recorded events
     */
    stopRecording(): RecordedInputEvent[] {
        this.config.recordInput = false;
        this.context.eventManager.emit("input-recording-stopped", {
            eventCount: this.recordedEvents.length,
        });
        return [...this.recordedEvents];
    }

    /**
     * Start playback of recorded events
     * @param events - Optional array of events to play back
     * @returns Promise that resolves when playback completes
     */
    startPlayback(events?: RecordedInputEvent[]): Promise<void> {
        if (events) {
            this.recordedEvents = events;
        }

        if (this.recordedEvents.length === 0) {
            throw new Error("No events to playback");
        }

        // Switch to mock input for playback
        if (!(this.inputSystem instanceof MockDeviceInputSystem)) {
            this.inputSystem.dispose();
            this.inputSystem = new MockDeviceInputSystem();
            this.inputSystem.attach(this.context.canvas);
            this.forwardInput(this.inputSystem);
        }

        this.playbackIndex = 0;
        this.playbackStartTime = Date.now();

        // Start playback loop and return the promise
        return this.runPlayback();
    }

    /**
     * Set up bridges between input system and event manager
     */
    private setupEventBridges(): void {
        // Only bridge events if enabled
        const createBridge = <T>(observable: Observable<T>, eventName: GraphEventType, shouldRecord = true): void => {
            observable.add((data) => {
                if (!this.enabled) {
                    return;
                }

                // Record event if recording
                if (this.config.recordInput && shouldRecord) {
                    this.recordedEvents.push({
                        timestamp: Date.now(),
                        type: eventName,
                        data: this.serializeEventData(data, true),
                    });
                }

                // Emit through event manager
                const eventData = this.serializeEventData(data);
                this.context.eventManager.emit(eventName, eventData);
            });
        };

        // Bridge all input events
        createBridge(this.onPointerMove, "input:pointer-move");
        createBridge(this.onPointerDown, "input:pointer-down");
        createBridge(this.onPointerUp, "input:pointer-up");
        createBridge(this.onWheel, "input:wheel");
        createBridge(this.onTouchStart, "input:touch-start");
        createBridge(this.onTouchMove, "input:touch-move");
        createBridge(this.onTouchEnd, "input:touch-end");
        createBridge(this.onKeyDown, "input:key-down");
        createBridge(this.onKeyUp, "input:key-up");

        // Special handling for keyboard shortcuts
        this.onKeyDown.add((info) => {
            if (!this.enabled) {
                return;
            }

            // Emit specific shortcut events. Ctrl on Windows and Linux, Cmd on macOS. Shift turns
            // the key upper case, so compare lower case: Ctrl/Cmd+Shift+Z is redo.
            if (!info.ctrlKey && !info.metaKey) {
                return;
            }

            const key = info.key.toLowerCase();
            const history = this.config.historyKeys === false ? undefined : this.config.history;
            if (key === "z" && !info.shiftKey) {
                this.context.eventManager.emit("input:undo", {});
                if (history !== undefined) {
                    info.preventDefault?.();
                    void history.undo();
                }
            } else if (key === "y" || (key === "z" && info.shiftKey)) {
                this.context.eventManager.emit("input:redo", {});
                if (history !== undefined) {
                    info.preventDefault?.();
                    void history.redo();
                }
            } else if (key === "a") {
                this.context.eventManager.emit("input:select-all", {});
            }
            // Add more shortcuts as needed
        });
    }

    /**
     * Serialize input data, as an `input:*` event detail or as a recording.
     * @param data - Event data to serialize
     * @param record - Keep every field, for a recording: playback reads a pointer's `button` and a
     *     touch's `id`, which the event detail leaves out (issue #3002).
     * @returns Serialized event data as a plain object
     */
    private serializeEventData(data: unknown, record = false): Record<string, unknown> {
        // An event detail gives a position (a Vector2, a pointer) as `{ x, y }` alone.
        if (
            !record &&
            data &&
            typeof data === "object" &&
            "x" in data &&
            "y" in data &&
            typeof data.x === "number" &&
            typeof data.y === "number"
        ) {
            return { x: data.x, y: data.y };
        }

        // Handle arrays
        if (Array.isArray(data)) {
            return { array: data.map((item) => this.serializeEventData(item, record)) };
        }

        // Handle objects. A callback (a key's `preventDefault`) is not data and is left out. A
        // field that is a primitive is kept as it is: the declared event types promise
        // `deltaY: number`, `key: string` (issue #2976).
        if (data && typeof data === "object") {
            const serialized: Record<string, unknown> = {};
            for (const [key, value] of Object.entries(data)) {
                if (typeof value === "function") {
                    continue;
                }
                serialized[key] =
                    value !== null && typeof value === "object" ? this.serializeEventData(value, record) : value;
            }
            return serialized;
        }

        // A primitive standing alone (an array item: a touch id) becomes a record, as
        // `InputTouchEndEvent` declares it.
        return { value: data };
    }

    /**
     * Run playback of recorded events
     */
    private async runPlayback(): Promise<void> {
        const mockSystem = this.inputSystem as MockDeviceInputSystem;

        while (this.playbackIndex < this.recordedEvents.length) {
            const event = this.recordedEvents[this.playbackIndex];
            const elapsed = Date.now() - this.playbackStartTime;
            const eventTime = event.timestamp - this.recordedEvents[0].timestamp;

            // Wait until it's time for this event
            if (elapsed < eventTime) {
                await new Promise((resolve) => setTimeout(resolve, eventTime - elapsed));
            }

            // Replay the event
            switch (event.type) {
                case "input:pointer-move":
                    mockSystem.simulateMouseMove(event.data.x as number, event.data.y as number, event.data);
                    break;
                case "input:pointer-down":
                    mockSystem.simulateMouseDown(event.data.button as MouseButton, event.data);
                    break;
                case "input:pointer-up":
                    mockSystem.simulateMouseUp(event.data.button as MouseButton, event.data);
                    break;
                case "input:wheel":
                    mockSystem.simulateWheel(event.data.deltaY as number, event.data.deltaX as number, event.data);
                    break;
                case "input:touch-start":
                    mockSystem.simulateTouchStart(event.data.array as TouchPoint[]);
                    break;
                case "input:touch-move":
                    mockSystem.simulateTouchMove(event.data.array as TouchPoint[]);
                    break;
                case "input:touch-end":
                    mockSystem.simulateTouchEnd((event.data.array as { value: number }[]).map((touch) => touch.value));
                    break;
                case "input:key-down":
                    mockSystem.simulateKeyDown(event.data.key as string, event.data);
                    break;
                case "input:key-up":
                    mockSystem.simulateKeyUp(event.data.key as string, event.data);
                    break;
                default:
                    // Unknown event type
                    break;
            }

            this.playbackIndex++;
        }

        this.context.eventManager.emit("input-playback-completed", {});
    }

    /**
     * Load playback file
     * @param filename - Path or URL to the playback file
     */
    private async loadPlaybackFile(filename: string): Promise<void> {
        try {
            const response = await fetch(filename);
            const data = await response.json();
            this.recordedEvents = data.events ?? [];
        } catch (error) {
            console.warn(`Failed to load playback file: ${filename}`, error);
        }
    }

    /**
     * Save recorded events (implementation depends on environment)
     */
    private saveRecordedEvents(): void {
        const data = {
            version: "1.0",
            timestamp: new Date().toISOString(),
            events: this.recordedEvents,
        };

        // In browser, download as file
        if (typeof window !== "undefined") {
            const blob = new Blob([JSON.stringify(data, null, 2)], {
                type: "application/json",
            });
            downloadBlob(blob, `input-recording-${Date.now()}.json`);
        }
    }

    /**
     * Update configuration
     * @param config - Partial configuration to merge with existing config
     */
    updateConfig(config: Partial<InputManagerConfig>): void {
        Object.assign(this.config, config);

        // Handle specific config changes
        if ("touchEnabled" in config || "keyboardEnabled" in config) {
            // These would affect input system behavior
            this.context.eventManager.emit("input-config-updated", config);
        }
    }

    /**
     * Enable pointer lock for FPS-style controls
     */
    async requestPointerLock(): Promise<void> {
        if (this.config.pointerLockEnabled) {
            try {
                await this.context.canvas.requestPointerLock();
                this.context.eventManager.emit("input-pointer-lock-changed", {
                    locked: true,
                });
            } catch (error) {
                console.warn("Failed to request pointer lock:", error);
            }
        }
    }

    /**
     * Exit pointer lock
     */
    exitPointerLock(): void {
        if (document.pointerLockElement === this.context.canvas) {
            document.exitPointerLock();
            this.context.eventManager.emit("input-pointer-lock-changed", {
                locked: false,
            });
        }
    }
}
