    isRunning(): boolean {
        return this.layoutManager.running;
    }

    /**
     * Set whether the layout engine should run.
     *
     * Resuming a simulation layout that had settled restarts it, so "play" moves nodes again;
     * pausing stops the per-frame stepping and nothing else. A pause holds until
     * `setRunning(true)`: loading data, setting a layout, an accelerator attaching or a drag
     * never resume it.
     * @param running - True to start the layout, false to stop it
     */
    setRunning(running: boolean): void {
        this.layoutManager.setPaused(!running);
    }

    /**
     * Get the current XR configuration.
     * @returns The XR configuration if set
     */
    getXRConfig(): XRConfig | undefined {
        return this.graphContext.getConfig().xr;
    }

    /**
     * Set XR configuration.
     * Merges the partial into the configuration in force, so `{ ui: { enabled: false } }` leaves
     * the rest as it was. After init the XR session manager and the canvas buttons are rebuilt
     * from it, ending an immersive session first, and `capabilities:changed` fires.
     * @param config - Partial XR configuration to apply
     */
    setXRConfig(config: PartialXRConfig): void {
        const current = this.xrConfig();
        const patch = config ?? {};
        const fullConfig = xrConfigSchema.parse({
            ...current,
            ...patch,
            ui: { ...current.ui, ...patch.ui },
            vr: { ...current.vr, ...patch.vr },
            ar: { ...current.ar, ...patch.ar },
            input: { ...current.input, ...patch.input },
            teleportation: { ...current.teleportation, ...patch.teleportation },
        });
        this.graphContext.updateConfig({ xr: fullConfig });
        if (this.initialized) {
            void this.reinitializeXR();
        }
    }

